input.content:
:root {
  --ink: #211c3a;
  --ink-soft: #3c3457;
  --muted: #675f7d;
  --paper: #fff9f2;
  --white: #ffffff;
  --line: #e8ddd5;
  --line-strong: #d7c8be;
  --brand: #5b36e9;
  --brand-dark: #4524bb;
  --brand-soft: #efe9ff;
  --coral: #c42f32;
  --coral-soft: #ffe7e4;
  --teal: #087f72;
  --teal-soft: #e0f7f3;
  --amber: #9a4c00;
  --amber-soft: #fff2d6;
  --pink: #b31968;
  --pink-soft: #ffe6f2;
  --cream-deep: #f7eee6;
  --success: #166a45;
  --success-soft: #e2f7eb;
  --danger: #a8232c;
  --danger-soft: #ffebed;
  --focus: #6d28d9;
  --shadow-sm: 0 8px 24px rgba(46, 33, 72, 0.08);
  --shadow-md: 0 20px 55px rgba(46, 33, 72, 0.12);
  --shadow-lg: 0 30px 80px rgba(46, 33, 72, 0.18);
  --radius-sm: 14px;
  --radius-md: 22px;
  --radius-lg: 30px;
  --radius-xl: 40px;
  --shell: 1180px;
  --font: "Avenir Next", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  background-color: var(--paper);
  background-image:
    radial-gradient(circle at 4% 4%, rgba(255, 191, 111, 0.18), transparent 26rem),
    radial-gradient(circle at 96% 13%, rgba(189, 164, 255, 0.16), transparent 30rem),
    radial-gradient(circle at 40% 90%, rgba(110, 231, 216, 0.1), transparent 32rem);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

body.modal-open {
  overflow: hidden;
}

h1,
h2,
h3,
h4,
p,
dl,
dd,
figure {
  margin-top: 0;
}

h1,
h2,
h3,
h4 {
  font-family: var(--font);
  line-height: 1.08;
  letter-spacing: -0.035em;
  color: var(--ink);
}

h1 {
  font-size: clamp(2.6rem, 6vw, 5rem);
  font-weight: 850;
}

h2 {
  font-size: clamp(1.8rem, 3.4vw, 2.7rem);
  font-weight: 820;
}

h3 {
  font-size: 1.25rem;
  font-weight: 780;
}

p {
  margin-bottom: 1rem;
}

a {
  color: var(--brand-dark);
  text-decoration-thickness: 0.12em;
  text-underline-offset: 0.18em;
}

a:hover {
  color: var(--ink);
}

img,
svg {
  display: block;
  max-width: 100%;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

ul,
ol {
  margin-top: 0;
}

[hidden] {
  display: none !important;
}

::selection {
  color: var(--ink);
  background: #ffd166;
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
  border-radius: 6px;
}

.sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 300;
  padding: 0.8rem 1.1rem;
  border-radius: 999px;
  background: var(--ink);
  color: var(--white);
  font-weight: 800;
  text-decoration: none;
  transform: translateY(-150%);
  transition: transform 160ms ease;
}

.skip-link:focus {
  transform: translateY(0);
  color: var(--white);
}

.shell {
  width: min(var(--shell), calc(100% - 2.5rem));
  margin-inline: auto;
}

.icon {
  width: 1.25rem;
  height: 1.25rem;
  flex: none;
}

.kicker {
  margin-bottom: 0.45rem;
  color: var(--coral);
  font-size: 0.75rem;
  font-weight: 850;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin-bottom: 1.4rem;
  padding: 0.45rem 0.85rem;
  border: 1px solid rgba(91, 54, 233, 0.16);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.72);
  color: var(--brand-dark);
  font-size: 0.79rem;
  font-weight: 800;
  letter-spacing: 0.035em;
}

.eyebrow-dot {
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: #12a47f;
  box-shadow: 0 0 0 4px rgba(18, 164, 127, 0.14);
}

.lede {
  max-width: 41rem;
  color: var(--ink-soft);
  font-size: clamp(1.04rem, 1.5vw, 1.2rem);
  line-height: 1.72;
}

.text-gradient {
  color: var(--brand-dark);
  background: linear-gradient(105deg, #5b36e9 8%, #b31968 58%, #9a4c00 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--brand-dark);
  font-weight: 800;
  text-decoration: none;
}

.text-link:hover {
  color: var(--ink);
  text-decoration: underline;
}

.text-link--muted {
  color: var(--muted);
}

.text-link--muted:hover {
  color: var(--ink);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 46px;
  padding: 0.76rem 1.2rem;
  border: 2px solid transparent;
  border-radius: 999px;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease, color 160ms ease;
}

.btn:hover {
  transform: translateY(-2px);
  text-decoration: none;
}

.btn:active {
  transform: translateY(0);
}

.btn-primary {
  background: var(--ink);
  color: var(--white);
  box-shadow: 0 10px 24px rgba(33, 28, 58, 0.2);
}

.btn-primary:hover {
  background: #34285f;
  color: var(--white);
}

.btn-light {
  background: var(--white);
  color: var(--ink);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.16);
}

.btn-light:hover {
  background: #fff4df;
  color: var(--ink);
}

.btn-outline-light {
  border-color: rgba(255, 255, 255, 0.58);
  background: transparent;
  color: var(--white);
}

.btn-outline-light:hover {
  border-color: var(--white);
  background: rgba(255, 255, 255, 0.12);
  color: var(--white);
}

.btn-ghost {
  border-color: var(--line-strong);
  background: var(--white);
  color: var(--ink);
}

.btn-ghost:hover {
  border-color: var(--brand);
  background: var(--brand-soft);
  color: var(--brand-dark);
}

.btn-small {
  min-height: 40px;
  padding: 0.55rem 0.9rem;
  font-size: 0.88rem;
}

.btn-wide {
  width: 100%;
}

.btn-soft {
  background: var(--brand-soft);
  color: var(--brand-dark);
}

.btn-soft:hover {
  background: #e2d8ff;
  color: var(--brand-dark);
}

.btn-danger-ghost {
  border-color: #f0c8cc;
  background: #fff7f7;
  color: var(--danger);
}

.btn-danger-ghost:hover {
  border-color: var(--danger);
  background: var(--danger-soft);
  color: var(--danger);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--ink);
  text-decoration: none;
}

.brand:hover {
  color: var(--ink);
}

.brand-mark {
  display: grid;
  width: 43px;
  height: 43px;
  flex: none;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, #5b36e9, #b31968 72%, #f08a24);
  color: var(--white);
  box-shadow: 0 8px 18px rgba(91, 54, 233, 0.24);
}

.brand-mark svg {
  width: 25px;
  height: 25px;
}

.brand-name {
  font-size: 1.03rem;
  font-weight: 850;
  line-height: 1.05;
  letter-spacing: -0.02em;
}

.brand-name span {
  display: block;
  margin-top: 0.22rem;
  color: var(--muted);
  font-size: 0.63rem;
  font-weight: 850;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  border-bottom: 1px solid rgba(232, 221, 213, 0.72);
  background: rgba(255, 249, 242, 0.88);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
}

.header-inner {
  position: relative;
  display: flex;
  min-height: 78px;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: 1.2rem;
}

.primary-nav ul {
  display: flex;
  align-items: center;
  gap: 0.15rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.primary-nav li a {
  display: block;
  padding: 0.62rem 0.88rem;
  border-radius: 999px;
  color: var(--ink-soft);
  font-size: 0.94rem;
  font-weight: 750;
  text-decoration: none;
  transition: background-color 150ms ease, color 150ms ease;
}

.primary-nav li a:hover {
  background: var(--brand-soft);
  color: var(--brand-dark);
}

.primary-nav li a[aria-current="page"] {
  background: var(--ink);
  color: var(--white);
}

.nav-cta {
  padding: 0.68rem 1.1rem;
  border: 2px solid var(--ink);
  border-radius: 999px;
  color: var(--ink);
  font-size: 0.9rem;
  font-weight: 850;
  text-decoration: none;
  transition: background-color 150ms ease, color 150ms ease;
}

.nav-cta:hover {
  background: var(--ink);
  color: var(--white);
}

.nav-toggle {
  display: none;
  align-items: center;
  gap: 0.65rem;
  min-height: 44px;
  padding: 0.55rem 0.75rem;
  border: 2px solid var(--line-strong);
  border-radius: 999px;
  background: var(--white);
  color: var(--ink);
  font-weight: 800;
}

.nav-toggle-icon {
  display: grid;
  width: 20px;
  gap: 4px;
}

.nav-toggle-icon span {
  display: block;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transition: transform 180ms ease, opacity 180ms ease;
}

.nav-toggle[aria-expanded="true"] .nav-toggle-icon span:nth-child(1) {
  transform: translateY(6px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] .nav-toggle-icon span:nth-child(2) {
  opacity: 0;
}

.nav-toggle[aria-expanded="true"] .nav-toggle-icon span:nth-child(3) {
  transform: translateY(-6px) rotate(-45deg);
}

.hero {
  position: relative;
  padding: clamp(3rem, 6vw, 5.5rem) 0 clamp(3rem, 6vw, 5rem);
  overflow: hidden;
}

.hero::before,
.hero::after {
  position: absolute;
  z-index: -1;
  border-radius: 50%;
  content: "";
  filter: blur(2px);
  pointer-events: none;
}

.hero::before {
  top: -11rem;
  right: -10rem;
  width: 42rem;
  height: 42rem;
  background: radial-gradient(circle, rgba(255, 178, 104, 0.34), rgba(255, 178, 104, 0) 69%);
}

.hero::after {
  bottom: -20rem;
  left: -17rem;
  width: 48rem;
  height: 48rem;
  background: radial-gradient(circle, rgba(133, 104, 255, 0.2), rgba(133, 104, 255, 0) 69%);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.16fr) minmax(310px, 0.84fr);
  gap: clamp(2rem, 5vw, 4.5rem);
  align-items: center;
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 1.45rem;
  font-size: clamp(3rem, 6.3vw, 5.6rem);
  font-weight: 900;
  letter-spacing: -0.06em;
  line-height: 0.97;
}

.hero .lede {
  max-width: 36rem;
  margin-bottom: 1.8rem;
}

.hero-search {
  display: flex;
  max-width: 40rem;
  align-items: center;
  gap: 0.55rem;
  padding: 0.45rem 0.45rem 0.45rem 1.1rem;
  border: 1px solid rgba(232, 221, 213, 0.9);
  border-radius: 999px;
  background: var(--white);
  box-shadow: var(--shadow-md);
}

.hero-search > svg {
  width: 1.35rem;
  height: 1.35rem;
  flex: none;
  color: var(--muted);
}

.hero-search input {
  width: 100%;
  min-width: 0;
  min-height: 46px;
  padding: 0.4rem 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
}

.hero-search input::placeholder {
  color: #8b829d;
  opacity: 1;
}

.hero-search:focus-within {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.hero-search .btn {
  min-height: 46px;
  flex: none;
}

.hero-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2rem;
  margin-top: 1.2rem;
  font-size: 0.92rem;
}

.hero-stats {
  display: flex;
  flex-wrap: wrap;
  gap: clamp(1.2rem, 4vw, 2.8rem);
  margin: 2.4rem 0 0;
  padding-top: 1.55rem;
  border-top: 1px solid var(--line);
}

.hero-stats div {
  display: flex;
  flex-direction: column-reverse;
  gap: 0.1rem;
}

.hero-stats dt {
  color: var(--muted);
  font-size: 0.77rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.hero-stats dd {
  margin: 0;
  font-size: 1.15rem;
  font-weight: 850;
}

.hero-art {
  position: relative;
  min-height: 480px;
  isolation: isolate;
}

.hero-art::before {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: -1;
  width: 28rem;
  height: 28rem;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 34%, #fff6cf, #ffd3bb 44%, #d4c4ff 76%, rgba(212, 196, 255, 0) 77%);
  content: "";
  transform: translate(-50%, -50%);
  opacity: 0.82;
}

.orbit {
  position: absolute;
  border: 1px solid rgba(91, 54, 233, 0.2);
  border-radius: 50%;
}

.orbit--one {
  top: 4%;
  left: 12%;
  width: 78%;
  aspect-ratio: 1;
  transform: rotate(18deg);
}

.orbit--two {
  top: 17%;
  left: 3%;
  width: 94%;
  aspect-ratio: 1;
  border-color: rgba(179, 25, 104, 0.14);
  transform: rotate(-14deg);
}

.floating-card {
  position: absolute;
  display: grid;
  gap: 0.28rem;
  width: min(245px, 70%);
  padding: 1rem 1.1rem;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-left: 6px solid var(--accent);
  border-radius: 19px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: var(--shadow-md);
  animation: float 6s ease-in-out infinite;
}

.floating-card strong {
  font-size: 1rem;
  line-height: 1.2;
}

.floating-card > span:last-child {
  color: var(--muted);
  font-size: 0.78rem;
}

.mini-code {
  color: var(--accent-ink);
  font-size: 0.68rem;
  font-weight: 850;
  letter-spacing: 0.1em;
}

.floating-card--one {
  top: 8%;
  left: 4%;
  transform: rotate(-5deg);
}

.floating-card--two {
  top: 39%;
  right: -1%;
  transform: rotate(4deg);
  animation-delay: -2.2s;
}

.floating-card--three {
  bottom: 7%;
  left: 8%;
  transform: rotate(-2deg);
  animation-delay: -4s;
}

.hero-badge {
  position: absolute;
  right: 3%;
  bottom: 13%;
  display: grid;
  width: 122px;
  height: 122px;
  place-content: center;
  border-radius: 50%;
  background: linear-gradient(145deg, #5b36e9, #b31968);
  color: var(--white);
  box-shadow: 0 18px 38px rgba(91, 54, 233, 0.28);
  text-align: center;
  transform: rotate(8deg);
}

.hero-badge strong {
  display: block;
  font-size: 2rem;
  line-height: 1;
}

.hero-badge span {
  display: block;
  max-width: 80px;
  margin: 0.28rem auto 0;
  font-size: 0.7rem;
  font-weight: 750;
  line-height: 1.2;
}

@keyframes float {
  0%,
  100% {
    margin-top: 0;
  }
  50% {
    margin-top: -10px;
  }
}

.theme-violet {
  --accent: #5b36e9;
  --accent-2: #a78bfa;
  --accent-soft: #efe9ff;
  --accent-ink: #4524bb;
}

.theme-teal {
  --accent: #087f72;
  --accent-2: #42cbb8;
  --accent-soft: #e0f7f3;
  --accent-ink: #05655b;
}

.theme-amber {
  --accent: #9a4c00;
  --accent-2: #ffc247;
  --accent-soft: #fff2d6;
  --accent-ink: #7a3c00;
}

.theme-coral {
  --accent: #c42f32;
  --accent-2: #ff8e83;
  --accent-soft: #ffe7e4;
  --accent-ink: #9e2326;
}

.theme-pink {
  --accent: #b31968;
  --accent-2: #ff83c1;
  --accent-soft: #ffe6f2;
  --accent-ink: #8c1150;
}

.theme-blue {
  --accent: #1d5bd8;
  --accent-2: #75a6ff;
  --accent-soft: #e6efff;
  --accent-ink: #1747ab;
}

.theme-emerald {
  --accent: #18794e;
  --accent-2: #54c891;
  --accent-soft: #e1f7eb;
  --accent-ink: #125f3e;
}

.theme-orange {
  --accent: #b8480a;
  --accent-2: #ff9f5b;
  --accent-soft: #ffeddf;
  --accent-ink: #913806;
}

.theme-rose {
  --accent: #b42a59;
  --accent-2: #ff7e9f;
  --accent-soft: #ffe5eb;
  --accent-ink: #8e1f45;
}

.theme-indigo {
  --accent: #3f3fb0;
  --accent-2: #8989ff;
  --accent-soft: #e9e9ff;
  --accent-ink: #333399;
}

.theme-cyan {
  --accent: #08718f;
  --accent-2: #4cc9e8;
  --accent-soft: #e0f7fc;
  --accent-ink: #065a72;
}

.theme-purple {
  --accent: #6b21a8;
  --accent-2: #bd7bff;
  --accent-soft: #f3e7ff;
  --accent-ink: #55198a;
}

.theme-fuchsia {
  --accent: #a21caf;
  --accent-2: #e879f9;
  --accent-soft: #fce7ff;
  --accent-ink: #84148e;
}

.theme-lime {
  --accent: #4d7c0f;
  --accent-2: #a3d93c;
  --accent-soft: #eef9d8;
  --accent-ink: #3d6209;
}

.theme-sky {
  --accent: #0369a1;
  --accent-2: #5bb9ee;
  --accent-soft: #e0f2fe;
  --accent-ink: #02527d;
}

.section {
  padding: clamp(3rem, 6vw, 5.2rem) 0;
}

.section--featured {
  padding-top: clamp(2rem, 4vw, 3.5rem);
}

.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.section-heading h2 {
  margin-bottom: 0;
}

.section-heading--center {
  justify-content: center;
  text-align: center;
}

.section-heading--center .kicker {
  margin-bottom: 0.6rem;
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  gap: 1.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.loading-card {
  grid-column: 1 / -1;
  padding: 2rem;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-md);
  color: var(--muted);
  background: rgba(255, 255, 255, 0.58);
  text-align: center;
}

.course-card {
  position: relative;
  display: flex;
  height: 100%;
  min-height: 100%;
  flex-direction: column;
  gap: 0.9rem;
  padding: 1.35rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--white);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.course-card::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 7px;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
  content: "";
}

.course-card:hover {
  border-color: rgba(91, 54, 233, 0.23);
  box-shadow: var(--shadow-md);
