}

.course-cell-title {
  display: block;
  color: var(--ink);
}

.course-cell-meta {
  display: block;
  margin-top: 0.15rem;
  color: var(--muted);
  font-size: 0.76rem;
  font-weight: 600;
}

.table-loading,
.table-empty {
  padding: 2.2rem 1rem;
  color: var(--muted);
  text-align: center;
}

.table-empty strong {
  display: block;
  margin-bottom: 0.3rem;
  color: var(--ink);
  font-size: 1rem;
}

.table-empty a {
  font-weight: 800;
}

.table-note {
  margin: 0.9rem 0 0;
  color: var(--muted);
  font-size: 0.78rem;
}

.profile-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.42fr) minmax(300px, 0.58fr);
  gap: 1.5rem;
  align-items: start;
}

.profile-panel {
  padding: clamp(1.3rem, 3.5vw, 2.1rem);
}

.profile-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.profile-avatar {
  display: grid;
  width: 82px;
  height: 82px;
  flex: none;
  place-items: center;
  border-radius: 50% 50% 50% 14px;
  background: linear-gradient(145deg, #5b36e9, #b31968 65%, #f08a24);
  color: var(--white);
  font-size: 1.35rem;
  font-weight: 850;
  letter-spacing: 0.02em;
  box-shadow: 0 12px 26px rgba(91, 54, 233, 0.23);
}

.profile-identity {
  min-width: 0;
  flex: 1;
}

.profile-identity .kicker {
  margin-bottom: 0.2rem;
}

.profile-identity h2 {
  margin-bottom: 0.2rem;
  font-size: 2rem;
}

.profile-identity p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 650;
}

.profile-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
  margin: 0;
}

.profile-details div {
  padding: 0.85rem 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: #fcfaf7;
}

.profile-details dt {
  margin-bottom: 0.15rem;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.profile-details dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 0.92rem;
  font-weight: 700;
}

.profile-form {
  padding-top: 0.3rem;
}

.profile-form h3 {
  margin-bottom: 1rem;
}

.snapshot-panel {
  padding: 1.5rem;
  background:
    radial-gradient(circle at 92% 3%, rgba(255, 193, 113, 0.3), transparent 11rem),
    var(--white);
}

.snapshot-panel h2 {
  margin-bottom: 1.1rem;
  font-size: 1.7rem;
}

.stat-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.7rem;
  margin: 0;
}

.stat-card {
  min-height: 105px;
  padding: 0.9rem;
  border-radius: 17px;
  background: var(--brand-soft);
}

.stat-card dt {
  color: var(--ink-soft);
  font-size: 0.72rem;
  font-weight: 750;
  line-height: 1.3;
}

.stat-card dd {
  margin: 0.7rem 0 0;
  overflow-wrap: anywhere;
  font-size: 1.7rem;
  font-weight: 850;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.stat-card--violet {
  background: #efe9ff;
  color: #4524bb;
}

.stat-card--teal {
  background: #e0f7f3;
  color: #05655b;
}

.stat-card--amber {
  background: #fff2d6;
  color: #7a3c00;
}

.stat-card--pink {
  background: #ffe6f2;
  color: #8c1150;
}

.stat-card--pink dd {
  font-size: 1.05rem;
  letter-spacing: -0.02em;
}

.snapshot-actions {
  display: grid;
  gap: 0.8rem;
  justify-items: center;
  margin-top: 1.2rem;
  text-align: center;
}

.snapshot-actions .text-link {
  font-size: 0.84rem;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: grid;
  place-items: center;
  padding: 1rem;
  background: rgba(22, 17, 40, 0.67);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  animation: fade-in 180ms ease both;
}

.modal {
  position: relative;
  width: min(530px, 100%);
  max-height: calc(100vh - 2rem);
  padding: clamp(1.5rem, 5vw, 2.3rem);
  border-radius: var(--radius-lg);
  background: var(--white);
  box-shadow: var(--shadow-lg);
  overflow-y: auto;
  animation: pop-in 220ms ease both;
}

.modal:focus {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.modal-close {
  position: absolute;
  top: 0.9rem;
  right: 0.9rem;
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--white);
  color: var(--ink);
}

.modal-close:hover {
  background: var(--brand-soft);
  color: var(--brand-dark);
}

.modal-close svg {
  width: 20px;
  height: 20px;
}

.modal-icon {
  display: grid;
  width: 68px;
  height: 68px;
  margin-bottom: 1.2rem;
  place-items: center;
  border-radius: 22px;
  background: linear-gradient(135deg, #087f72, #12a47f);
  color: var(--white);
  box-shadow: 0 12px 26px rgba(8, 127, 114, 0.24);
}

.modal-icon svg {
  width: 36px;
  height: 36px;
}

.modal .kicker {
  color: var(--teal);
}

.modal h2 {
  margin-bottom: 0.65rem;
  font-size: clamp(1.9rem, 5vw, 2.5rem);
}

.modal > p:not(.kicker) {
  color: var(--muted);
}

.confirmation-details {
  display: grid;
  gap: 0.6rem;
  margin: 1.3rem 0 1.5rem;
  padding: 1rem 1.1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: #fcfaf7;
}

.confirmation-details div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.confirmation-details dt {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 700;
}

.confirmation-details dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 0.87rem;
  font-weight: 750;
  text-align: right;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.7rem;
}

.modal-actions .btn-primary {
  flex: 1 1 180px;
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.toast {
  position: fixed;
  bottom: 1.25rem;
  left: 50%;
  z-index: 250;
  display: flex;
  width: max-content;
  max-width: calc(100% - 2rem);
  align-items: center;
  gap: 1rem;
  padding: 0.78rem 1rem;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 999px;
  background: var(--ink);
  color: var(--white);
  box-shadow: var(--shadow-lg);
  transform: translateX(-50%);
  animation: toast-in 200ms ease both;
}

.toast-message {
  font-size: 0.85rem;
  font-weight: 700;
}

.toast-undo {
  flex: none;
  padding: 0.15rem 0.2rem;
  border: 0;
  background: transparent;
  color: #ffd166;
  font-size: 0.84rem;
  font-weight: 850;
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

.toast-undo:hover {
  color: var(--white);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translate(-50%, 12px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.site-footer {
  margin-top: clamp(3rem, 6vw, 5rem);
  padding: clamp(2.5rem, 5vw, 3.8rem) 0 1.5rem;
  background:
    radial-gradient(circle at 88% 10%, rgba(179, 25, 104, 0.32), transparent 22rem),
    radial-gradient(circle at 8% 100%, rgba(91, 54, 233, 0.26), transparent 25rem),
    #1b172b;
  color: #d9d3e8;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr 0.7fr 1fr;
  gap: 3rem;
}

.brand--footer {
  color: var(--white);
}

.brand--footer:hover {
  color: var(--white);
}

.brand--footer .brand-name span {
  color: #b8afce;
}

.footer-brand p {
  max-width: 25rem;
  margin: 1rem 0 0;
  color: #b8afce;
  font-size: 0.9rem;
}

.footer-nav h2,
.footer-help h2 {
  margin-bottom: 0.8rem;
  color: var(--white);
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.footer-nav ul {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.footer-nav a,
.footer-help a {
  color: #d9d3e8;
  font-size: 0.9rem;
  font-weight: 600;
}

.footer-nav a:hover,
.footer-help a:hover {
  color: var(--white);
}

.footer-help p {
  margin-bottom: 0.6rem;
  color: #b8afce;
  font-size: 0.88rem;
}

.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 2.5rem;
  padding-top: 1.2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.13);
}

.footer-bottom p {
  margin: 0;
  color: #a79dbf;
  font-size: 0.76rem;
}

@media (max-width: 980px) {
  .hero-grid {
    grid-template-columns: minmax(0, 1.15fr) minmax(260px, 0.85fr);
    gap: 1.8rem;
  }

  .hero-art {
    min-height: 420px;
  }

  .floating-card {
    width: min(225px, 78%);
  }

  .hero-badge {
    width: 104px;
    height: 104px;
  }

  .hero-badge strong {
    font-size: 1.7rem;
  }

  .filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .filter-reset {
    justify-self: start;
  }

  .registration-layout,
  .profile-layout {
    grid-template-columns: 1fr;
  }

  .summary-sticky {
    position: static;
  }
}

@media (max-width: 860px) {
  .nav-toggle {
    display: inline-flex;
  }

  .primary-nav {
    position: absolute;
    top: calc(100% + 0.55rem);
    right: 0;
    left: 0;
    display: none;
    flex-direction: column;
    align-items: stretch;
    gap: 0.7rem;
    padding: 0.8rem;
    border: 1px solid var(--line);
    border-radius: var(--radius-md);
    background: var(--white);
    box-shadow: var(--shadow-md);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav ul {
    flex-direction: column;
    align-items: stretch;
    gap: 0.15rem;
  }

  .primary-nav li a {
    padding: 0.75rem 0.9rem;
    border-radius: 12px;
  }

  .nav-cta {
    display: block;
    padding: 0.75rem 0.9rem;
    border-radius: 12px;
    text-align: center;
  }

  .hero-grid {
    grid-template-columns: 1fr;
  }

  .hero-copy {
    max-width: 46rem;
  }

  .hero-art {
    display: none;
  }

  .steps-grid {
    grid-template-columns: 1fr;
  }

  .cta-band {
    align-items: flex-start;
    flex-direction: column;
  }

  .page-hero-content {
    align-items: flex-start;
    flex-direction: column;
  }

  .catalog-doodle,
  .page-stamp,
  .profile-hero-badge {
    display: none;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-brand {
    grid-column: 1 / -1;
  }
}

@media (max-width: 680px) {
  .shell {
    width: min(var(--shell), calc(100% - 1.4rem));
  }

  .header-inner {
    min-height: 70px;
  }

  .brand-name {
    font-size: 0.95rem;
  }

  .hero {
    padding-top: 2.4rem;
  }

  .hero h1 {
    font-size: clamp(2.65rem, 13vw, 4rem);
  }

  .hero-search {
    flex-wrap: wrap;
    padding: 0.55rem;
    border-radius: 22px;
  }

  .hero-search > svg {
    margin-left: 0.5rem;
  }

  .hero-search input {
    width: calc(100% - 2.3rem);
  }

  .hero-search .btn {
    width: 100%;
  }

  .hero-stats {
    gap: 1.3rem;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.8rem;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .form-grid,
  .profile-details {
    grid-template-columns: 1fr;
  }

  .panel-heading {
    flex-direction: column;
    gap: 0.4rem;
  }

  .filter-grid {
    grid-template-columns: 1fr;
  }

  .filter-reset {
    width: 100%;
  }

  .results-bar {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.2rem;
  }

  .schedule-heading-row {
    flex-direction: row;
    align-items: flex-end;
  }

  .profile-header {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .profile-avatar {
    width: 68px;
    height: 68px;
  }

  .profile-identity h2 {
    font-size: 1.7rem;
  }

  .profile-header .btn {
    margin-left: auto;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-brand {
    grid-column: auto;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 0.4rem;
  }

  .modal-actions {
    flex-direction: column;
  }

  .modal-actions .btn {
    width: 100%;
  }

  .toast {
    align-items: flex-start;
    border-radius: 18px;
  }
}

@media (max-width: 420px) {
  .brand-mark {
    width: 39px;
    height: 39px;
  }

  .nav-toggle-label {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .hero-links {
    flex-direction: column;
    gap: 0.55rem;
  }

  .hero-stats {
    justify-content: space-between;
  }

  .hero-stats dd {
    font-size: 1rem;
  }

  .stat-list {
    grid-template-columns: 1fr;
  }

  .stat-card {
    min-height: 86px;
  }

  .profile-header .btn {
    width: 100%;
    margin-left: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

