    if (course.seats <= 5) {
      return {
        className: "seat-status--low",
        label: pluralize(course.seats, "seat", "seats") + " left"
      };
    }
    return {
      className: "",
      label: pluralize(course.seats, "seat", "seats") + " left"
    };
  }

