        '<p class="course-dept">' + escapeHTML(course.department) + '</p>' +
        '<h3 id="course-' + escapeHTML(course.id) + '-title">' + escapeHTML(course.title) + '</h3>' +
        '<p class="course-desc">' + escapeHTML(course.description) + '</p>' +
