from html.parser import HTMLParser
from pathlib import Path
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack=[]
        self.errors=[]
        self.void={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void: return
        if not self.stack:
            self.errors.append(f'extra closing {tag}')
        elif self.stack[-1]!=tag:
            if tag in self.stack:
                self.errors.append(f'unexpected closing {tag}, open stack tail {self.stack[-5:]}')
                while self.stack and self.stack[-1]!=tag: self.stack.pop()
                if self.stack: self.stack.pop()
            else:
                self.errors.append(f'closing {tag} without open')
        else:
            self.stack.pop()
for f in Path('.').glob('*.html'):
    p=P(); p.feed(f.read_text())
    print(f, 'stack', p.stack, 'errors', p.errors[:10])
