const http = require('http');
const fs = require('fs');
const path = require('path');
const { JSDOM, VirtualConsole } = require('jsdom');

const root = '/work';
const types = {'.html':'text/html','.css':'text/css','.js':'text/javascript','.svg':'image/svg+xml'};
const server = http.createServer((req,res)=>{
  const urlPath = decodeURIComponent(req.url.split('?')[0]);
  const file = path.join(root, urlPath === '/' ? 'index.html' : urlPath);
  if (!file.startsWith(root) || !fs.existsSync(file)) { res.writeHead(404); res.end('not found'); return; }
  res.writeHead(200, {'Content-Type': types[path.extname(file)] || 'application/octet-stream'});
  fs.createReadStream(file).pipe(res);
});

function waitLoad(dom) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('load timeout')), 5000);
    dom.window.addEventListener('load', () => { clearTimeout(t); setTimeout(resolve, 80); });
  });
}

async function load(page) {
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push('jsdomError: ' + e.message));
  vc.on('error', (...args) => errors.push('console.error: ' + args.join(' ')));
  const dom = await JSDOM.fromURL(`http://127.0.0.1:8899/${page}`, {
    runScripts: 'dangerously', resources: 'usable', pretendToBeVisual: true, virtualConsole: vc
  });
  await waitLoad(dom);
  return { dom, doc: dom.window.document, win: dom.window, errors };
}

function assert(cond, msg) { if (!cond) throw new Error('ASSERT: ' + msg); }

(async () => {
  await new Promise(r => server.listen(8899, '127.0.0.1', r));

  {
    const { dom, doc, win, errors } = await load('index.html');
    assert(errors.length === 0, 'index errors ' + errors.join('; '));
    assert(doc.querySelectorAll('.course-card').length === 4, 'featured cards');
    assert(doc.querySelectorAll('#primary-nav a[aria-current="page"]').length === 1, 'current page nav');
    const toggle = doc.querySelector('.nav-toggle');
    toggle.click();
    assert(toggle.getAttribute('aria-expanded') === 'true', 'nav opens');
    assert(doc.querySelector('#primary-nav').classList.contains('is-open'), 'nav class');
    toggle.click();
    assert(toggle.getAttribute('aria-expanded') === 'false', 'nav closes');
    assert(doc.querySelector('[data-course-count]').textContent === '16', 'course count');
    console.log('PASS home');
    win.close();
  }

  {
    const { dom, doc, win, errors } = await load('catalog.html?q=climate');
    assert(errors.length === 0, 'catalog errors ' + errors.join('; '));
    assert(doc.querySelectorAll('#course-list .course-card').length === 1, 'climate search one');
    assert(doc.querySelector('#results-count').textContent.includes('1 of 16'), 'search count');
    const search = doc.querySelector('#catalog-search');
    search.value = '';
    search.dispatchEvent(new win.Event('input', {bubbles:true}));
    assert(doc.querySelectorAll('#course-list .course-card').length === 16, 'clear search shows all');
    const dept = doc.querySelector('#department-filter');
    dept.value = 'Design';
    dept.dispatchEvent(new win.Event('change', {bubbles:true}));
    assert(doc.querySelectorAll('#course-list .course-card').length === 2, 'design filter');
    assert(doc.querySelectorAll('#course-list .course-card .course-card__header .course-code')[0].textContent === 'DES 120', 'design sort featured');
    const level = doc.querySelector('#level-filter');
    level.value = '300';
    level.dispatchEvent(new win.Event('change', {bubbles:true}));
    assert(doc.querySelectorAll('#course-list .course-card').length === 0, 'empty filtered');
    assert(doc.querySelector('#empty-state').hidden === false, 'empty state visible');
    doc.querySelector('#empty-reset').click();
    assert(doc.querySelectorAll('#course-list .course-card').length === 16, 'reset filters');
    const sort = doc.querySelector('#sort-filter');
    sort.value = 'seats';
    sort.dispatchEvent(new win.Event('change', {bubbles:true}));
    const firstSeats = doc.querySelector('#course-list .course-card .seat-status').textContent;
    assert(firstSeats.includes('30'), 'sort by seats first is 30 left, got ' + firstSeats);
    console.log('PASS catalog');
    win.close();
  }

  {
    const { dom, doc, win, errors } = await load('registration.html?course=fil260');
    assert(errors.length === 0, 'registration errors ' + errors.join('; '));
    assert(doc.querySelectorAll('#course-select option').length === 17, 'course options');
    assert(doc.querySelector('#course-select').value === 'fil260', 'query preselect');
    assert(doc.querySelector('#fullName').value === 'Alex Morgan', 'profile prefill');
    assert(doc.querySelectorAll('#registered-courses-body tr').length === 2, 'default rows');
    assert(doc.querySelector('#course-summary').textContent.includes('Documentary Practice'), 'summary selected');

    const form = doc.querySelector('#registration-form');
    form.querySelector('#semester').value = 'Spring 2027';
    form.dispatchEvent(new win.Event('submit', {bubbles:true, cancelable:true}));
    assert(doc.querySelector('#confirmation-modal').hidden === false, 'modal open');
    assert(doc.querySelectorAll('#registered-courses-body tr').length === 3, 'table after register');
    assert(doc.querySelector('[data-registration-count]').textContent === '3 courses', 'count after register');
    assert(doc.querySelector('#confirmation-course').textContent.includes('FIL 260'), 'modal course');
    assert(win.localStorage.getItem('campusCourseHub.registrations.v1').includes('fil260'), 'stored registration');

    doc.querySelector('#modal-close').click();
    assert(doc.querySelector('#confirmation-modal').hidden === true, 'modal closed');

    const select = doc.querySelector('#course-select');
    select.value = 'fil260';
    select.dispatchEvent(new win.Event('change', {bubbles:true}));
    form.dispatchEvent(new win.Event('submit', {bubbles:true, cancelable:true}));
    assert(doc.querySelector('#registration-errors').hidden === false, 'duplicate error summary');
    assert(doc.querySelector('#courseId-error').hidden === false, 'duplicate inline error');
    assert(doc.querySelector('#course-select').getAttribute('aria-invalid') === 'true', 'duplicate aria invalid');

    const drop = doc.querySelector('button[data-drop-course="fil260"]');
    drop.click();
    assert(doc.querySelectorAll('#registered-courses-body tr').length === 2, 'table after drop');
    assert(doc.querySelector('#app-toast').hidden === false, 'toast visible');
    doc.querySelector('.toast-undo').click();
    assert(doc.querySelectorAll('#registered-courses-body tr').length === 3, 'undo restores');
    console.log('PASS registration flow');
    win.close();
  }

  {
    const { dom, doc, win, errors } = await load('profile.html');
    assert(errors.length === 0, 'profile errors ' + errors.join('; '));
    assert(doc.querySelector('#profile-display-name').textContent === 'Alex Morgan', 'profile name');
    assert(doc.querySelector('#profile-hero-name').textContent === 'Alex', 'hero first name');
    assert(doc.querySelector('[data-stat-courses]').textContent === '2', 'stat courses');
    assert(doc.querySelector('[data-stat-credits]').textContent === '6', 'stat credits');
    assert(doc.querySelector('[data-stat-departments]').textContent === '2', 'stat departments');
    assert(doc.querySelectorAll('#registered-courses-body tr').length === 2, 'profile rows');

    doc.querySelector('#edit-profile-btn').click();
    assert(doc.querySelector('#profile-edit-form').hidden === false, 'edit form visible');
    assert(doc.activeElement.id === 'profile-name-input', 'focus first profile input');
    const nameInput = doc.querySelector('#profile-name-input');
    nameInput.value = 'Jamie Rivera';
    doc.querySelector('#profile-edit-form').dispatchEvent(new win.Event('submit', {bubbles:true, cancelable:true}));
    assert(doc.querySelector('#profile-display-name').textContent === 'Jamie Rivera', 'profile updated');
    assert(doc.querySelector('#profile-avatar').textContent === 'JR', 'avatar initials');
    assert(doc.querySelector('#profile-edit-form').hidden === true, 'edit form closed');
    assert(win.localStorage.getItem('campusCourseHub.profile.v1').includes('Jamie Rivera'), 'stored profile');
    console.log('PASS profile');
    win.close();
  }

  server.close();
  console.log('\nALL TESTS PASSED');
})().catch(async (e) => {
  console.error(e.stack || e);
  server.close();
  process.exit(1);
});
