from html.parser import HTMLParser
from pathlib import Path
from collections import Counter
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.ids=[]; self.refs=[]; self.labels=[]; self.controls=[]; self.headings=[]; self.imgs=[]; self.inputs=[]; self.buttons=[]; self.forms=[]; self.tables=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.append(d['id'])
        for k in ['aria-labelledby','aria-describedby','aria-controls']:
            if k in d:
                for i in d[k].split(): self.refs.append((tag,k,i))
        if tag=='label' and 'for' in d: self.labels.append(d['for'])
        if tag in ('input','select','textarea') and 'id' in d: self.controls.append(d['id'])
        if tag in ('h1','h2','h3','h4','h5','h6'): self.headings.append((tag,d.get('id'),d))
        if tag=='img': self.imgs.append(d)
        if tag in ('input','select','textarea'): self.inputs.append((tag,d))
        if tag=='button': self.buttons.append(d)
        if tag=='form': self.forms.append(d)
        if tag=='table': self.tables.append(d)
for f in Path('.').glob('*.html'):
    p=P(); p.feed(f.read_text())
    dup=[i for i,c in Counter(p.ids).items() if c>1]
    missing=[r for r in p.refs if r[2] not in p.ids]
    label_missing=[l for l in p.labels if l not in p.ids]
    inputs_no_id=[(t,d) for t,d in p.inputs if 'id' not in d and d.get('type') not in ('hidden','submit')]
    h1=[h for h in p.headings if h[0]=='h1']
    print('\n',f)
    print(' dup ids',dup)
    print(' missing aria refs',missing)
    print(' label for missing',label_missing)
    print(' inputs no id',inputs_no_id)
    print(' h1 count',len(h1))
    print(' buttons no type',[b for b in p.buttons if 'type' not in b])
    print(' forms',p.forms,'tables',p.tables)
