from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urlparse
class L(HTMLParser):
    def __init__(self): super().__init__(); self.links=[]; self.ids=set()
    def handle_starttag(self,tag,attrs):
        d=dict(attrs)
        if 'id' in d: self.ids.add(d['id'])
        if tag in ('a','link','script') and ('href' in d or 'src' in d):
            self.links.append(d.get('href') or d.get('src'))
files={p.name:p for p in Path('.').glob('*.html')}
for name,p in files.items():
    l=L(); l.feed(p.read_text())
    for link in l.links:
        if link.startswith(('http','mailto:','data:')): continue
        u=urlparse(link)
        target=u.path or name
        if target not in files:
            print(name,'MISSING FILE',link)
        elif u.fragment:
            t=L(); t.feed(files[target].read_text())
            if u.fragment not in t.ids:
                print(name,'MISSING ANCHOR',link)
print('link check done')
